def get_good_triples(limit):
    good_triples = []
    for x in range(-limit, limit + 1):
        for y in range(-limit, limit + 1):
            for z in range(-limit, limit + 1):
                # Calculate y^x * z^y * x^z
                # We must handle potential issues like 0^0, 0^negative, and non-integer results
                # Since we are looking for prime numbers, we can skip cases where y, z, or x is 0
                # if the power is not positive.
                try:
                    # Using complex to handle potentially negative numbers to a power
                    # But the problem says x, y, z are integers.
                    # If x, y, z are integers, y^x is (1/y)^(-x) if x < 0.
                    # To avoid precision issues, we use fraction or check if it's an integer.

                    # If x, y, z are integers, y^x can be a fraction.
                    # Let's compute it using the definition.

                    def safe_pow(base, exponent):
                        if base == 0:
                            if exponent > 0: return 0
                            if exponent == 0: return 1 # 0^0 is usually 1
                            else: return float('inf') # 0^negative is undefined
                        if exponent < 0:
                            return 1 / (base**(-exponent))
                        else:
                            return base**exponent

                    val_yx = safe_pow(y, x)
                    val_zy = safe_pow(z, y)
                    val_xz = safe_pow(x, z)

                    val = val_yx * val_zy * val_xz

                    # Check if val is a positive prime
                    if abs(val - round(val)) < 1e-9:
                        val_int = int(round(val))
                        if is_prime(val_int):
                            good_triples.append((x, y, z, x**2 + y**2 + z**2))
                except (ZeroDivisionError, ValueError, OverflowError):
                    continue
    return good_triples

